import random
import struct
from typing import List, Tuple

# Generator for valid GIF extension sub-block payloads (0..255 bytes).
# Designed to exercise encoder/decoder paths that accept FUZZ_PARAM_STR buffers
# for various extension types: Comment (0xFE), Graphics Control (0xF9),
# Plain Text (0x01), Application (0xFF), and Continuation (0x00).
#
# Strategy:
# - Randomly pick one of several templates producing valid payloads for each
#   extension kind, keeping size within 0..255.
# - Include variety: minimal/edge sizes, different ASCII lengths, plausible
#   application IDs/auth codes, and well-formed Graphics Control payloads.
# - Returned bytes can be used directly as the data for a single sub-block.
#   Fuzzer stubs cap sizes (<=255 or smaller), so we respect those limits.

ASCII = [c for c in range(0x20, 0x7F)]  # printable ASCII (space..~)


def _rand_ascii(rng: random.Random, min_len: int, max_len: int) -> bytes:
    n = rng.randint(min_len, max_len)
    return bytes(rng.choice(ASCII) for _ in range(n))


def _comment_payload(rng: random.Random) -> bytes:
    # Comment extension: arbitrary text, 0..255 bytes.
    # Include chance of empty, short, long near limit.
    modes = [0, 1, 2, 3]
    m = rng.choice(modes)
    if m == 0:
        return b""  # empty sub-block valid as terminator or empty data
    elif m == 1:
        return _rand_ascii(rng, 1, 32)
    elif m == 2:
        return _rand_ascii(rng, 33, 128)
    else:
        # near upper bound
        return _rand_ascii(rng, 200, 255)


def _graphics_control_payload(rng: random.Random) -> bytes:
    # Graphics Control Extension payload is 4 bytes (packed fields):
    # [Packed Fields][Delay LSB][Delay MSB][Transparent Color Index]
    # We generate consistent combinations.
    disposal_modes = [0, 1, 2, 3]
    disposal = rng.choice(disposal_modes) & 0x7
    user_input = rng.choice([0, 1])
    has_transparent = rng.choice([0, 1])
    packed = (disposal << 2) | (user_input << 1) | (has_transparent)
    delay = rng.choice([0, 1, 2, 5, 10, 25, 50, 100, rng.randint(0, 65535)])
    trans_index = rng.randint(0, 255) if has_transparent else 0
    payload = bytes([
        packed & 0xFF,
        delay & 0xFF,
        (delay >> 8) & 0xFF,
        trans_index & 0xFF,
    ])
    # Occasionally return alternative valid sizes used by some tooling (still 4).
    return payload


def _plaintext_payload(rng: random.Random) -> bytes:
    # Plain Text Extension sub-block content is arbitrary bytes; however, to be
    # meaningful, implementations expect ASCII. We produce short ASCII text.
    # Valid sub-block size range is 0..255.
    # Include empty as well.
    choose = rng.randint(0, 3)
    if choose == 0:
        return b""
    elif choose == 1:
        return _rand_ascii(rng, 1, 40)
    elif choose == 2:
        return _rand_ascii(rng, 41, 120)
    else:
        return _rand_ascii(rng, 200, 255)


def _application_payload(rng: random.Random) -> bytes:
    # Application extension streams begin with an 11-byte header across sub-blocks
    # (8-byte Application Identifier + 3-byte Authentication Code). The fuzzer
    # provides only a single sub-block buffer at a time; we craft a plausible
    # first sub-block containing that 11-byte header plus some data, kept <=255.
    # Common IDs: "NETSCAPE" (looping), "ANIMEXTS".
    common_ids = [b"NETSCAPE", b"ANIMEXTS", b"XMP Data", b"ICCRGBG "]
    app_id = rng.choice(common_ids)
    # Ensure exactly 8 bytes (pad with space or trim)
    if len(app_id) < 8:
        app_id = app_id + b" " * (8 - len(app_id))
    elif len(app_id) > 8:
        app_id = app_id[:8]
    auth = bytes(rng.choice(ASCII) for _ in range(3))

    # Optionally add payload like NETSCAPE loop sub-block data: 0x01, loops LSB, MSB
    add_netscape_data = rng.choice([True, False])
    body = b""
    if add_netscape_data:
        loops = rng.choice([0, 1, 10, 100, 65535, rng.randint(0, 65535)])
        body = bytes([0x01, loops & 0xFF, (loops >> 8) & 0xFF])
    else:
        # arbitrary ASCII payload up to remaining space
        body = _rand_ascii(rng, 0, 200)

    payload = app_id + auth + body
    if len(payload) > 255:
        payload = payload[:255]
    return payload


def _continuation_payload(rng: random.Random) -> bytes:
    # Continuation sub-blocks are just arbitrary bytes. Provide varied sizes.
    choice = rng.randint(0, 3)
    if choice == 0:
        return b""
    elif choice == 1:
        return _rand_ascii(rng, 1, 64)
    elif choice == 2:
        return _rand_ascii(rng, 65, 180)
    else:
        return _rand_ascii(rng, 181, 255)


def _pick_payload(rng: random.Random) -> bytes:
    # Randomly choose an extension style to generate a payload for.
    generators = [
        _comment_payload,
        _graphics_control_payload,
        _plaintext_payload,
        _application_payload,
        _continuation_payload,
    ]
    gen = rng.choice(generators)
    return gen(rng)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Sometimes bias towards the specific stub size limits for certain targets
    # (e.g., 32 or 64 bytes) by trimming after generation.
    payload = _pick_payload(rng)

    # With small probability, adapt to small caps used in some stubs (<=64 or <=32)
    cap_choice = rng.random()
    if cap_choice < 0.15:
        cap = 32
    elif cap_choice < 0.30:
        cap = 64
    else:
        cap = 255
    if len(payload) > cap:
        payload = payload[:cap]

    # Ensure maximum buffer size policy remains well within global limit.
    if len(payload) > 4096:
        payload = payload[:4096]
    return payload

import random
import struct
from typing import List

# Generator for a writable byte buffer used by DGifGetLine.
# The fuzzer stub uses FUZZ_PARAM_STR() to create a mutable buffer and then
# interprets it as GifPixelType* (unsigned char*) and passes its size (1..1024)
# as GifLineLen. Our job is to provide initial contents that are valid and
# interesting as pixel indices for various plausible GIF color table sizes.
#
# Considerations:
# - Pixel values are palette indices 0..255. Any byte is valid.
# - Interesting patterns include: constant fills, ramps, stripes, checkerboards,
#   gradients, alternating values, and blocks matching common palette sizes
#   (2, 4, 8, 16, 32, 64, 128, 256).
# - Length must be between 1 and 1024 bytes; we will vary lengths to exercise
#   short and long lines.
# - Data must be valid (not malformed); any byte values are fine as indices.
#
# The generate(seed) function returns a bytes object up to 1024 bytes.

_MAX_LEN = 1024

def _rand_len(rnd: random.Random) -> int:
    # Bias toward powers-of-two and some typical widths (1, 2, 3, 4, 7, 8, 16, 31, 32, 63, 64, 127, 128, 255, 256, 512, 1024)
    choices = [1,2,3,4,7,8,15,16,31,32,63,64,127,128,255,256,512,1024]
    if rnd.random() < 0.7:
        return rnd.choice(choices)
    return rnd.randint(1, _MAX_LEN)

def _pattern_constant(length: int, value: int) -> bytes:
    return bytes([value & 0xFF]) * length

def _pattern_ramp(length: int, start: int, step: int) -> bytes:
    arr = bytearray(length)
    v = start & 0xFF
    for i in range(length):
        arr[i] = v
        v = (v + step) & 0xFF
    return bytes(arr)

def _pattern_alternating(length: int, a: int, b: int) -> bytes:
    arr = bytearray(length)
    aa, bb = a & 0xFF, b & 0xFF
    for i in range(length):
        arr[i] = aa if (i & 1) == 0 else bb
    return bytes(arr)

def _pattern_repeat_block(length: int, block: bytes) -> bytes:
    if not block:
        return bytes(length)
    repeats, rem = divmod(length, len(block))
    return block * repeats + block[:rem]

def _palette_cycle_block(palette_size: int) -> bytes:
    # Create a block cycling through 0..palette_size-1
    return bytes([i % 256 for i in range(palette_size)])

def _checker(length: int, period: int, vals: List[int]) -> bytes:
    # Repeats a sequence of vals over a given period; typical for stripes/checkers
    period = max(1, period)
    seq = bytes([vals[i % len(vals)] & 0xFF for i in range(period)])
    return _pattern_repeat_block(length, seq)

def _gradient(length: int, start: int, end: int) -> bytes:
    if length <= 1:
        return bytes([start & 0xFF])
    arr = bytearray(length)
    s = start & 0xFF
    e = end & 0xFF
    # Linear gradient in byte space (wrap-aware via modular interpolation)
    # Use simple integer interpolation without wrap to keep values smooth.
    for i in range(length):
        t = i / (length - 1)
        val = int(round(s * (1 - t) + e * t)) & 0xFF
        arr[i] = val
    return bytes(arr)

def _blocks_of_color(length: int, block_len: int, colors: List[int]) -> bytes:
    block_len = max(1, block_len)
    out = bytearray()
    color_idx = 0
    while len(out) < length:
        c = colors[color_idx % len(colors)] & 0xFF
        out.extend(bytes([c]) * block_len)
        color_idx += 1
    return bytes(out[:length])

def _make_interesting_buffer(rnd: random.Random, length: int) -> bytes:
    # Choose among various patterns
    palettes = [2,4,8,16,32,64,128,256]
    choice = rnd.randrange(0, 11)

    if choice == 0:
        # Constant fill with edge indices
        value = rnd.choice([0,1,2,127,128,254,255])
        return _pattern_constant(length, value)
    elif choice == 1:
        # Simple ramp with step 1 or power-of-two steps
        step = rnd.choice([1,2,3,4,7,8,15,16,31,32,63,64])
        start = rnd.randrange(0, 256)
        return _pattern_ramp(length, start, step)
    elif choice == 2:
        # Alternating two colors (e.g., transparency vs foreground)
        a = rnd.choice([0,255,1,2,127])
        b = rnd.choice([0,255,3,4,128])
        return _pattern_alternating(length, a, b)
    elif choice == 3:
        # Repeated small block (e.g., 4- or 8-wide pattern)
        block_sizes = [3,4,5,6,7,8,16]
        bs = rnd.choice(block_sizes)
        block = bytes(rnd.randrange(0,256) for _ in range(bs))
        return _pattern_repeat_block(length, block)
    elif choice == 4:
        # Palette cycle for a random palette size
        ps = rnd.choice(palettes)
        block = _palette_cycle_block(ps)
        return _pattern_repeat_block(length, block)
    elif choice == 5:
        # Checker/stripe patterns with selected values
        period = rnd.choice([2,3,4,8,16,32])
        vals = [rnd.choice([0,1,2,3,127,128,254,255]) for _ in range(rnd.choice([2,3,4]))]
        return _checker(length, period, vals)
    elif choice == 6:
        # Gradient between two extremes
        start = rnd.choice([0, 16, 32, 64, 96, 128, 160, 192, 224, 255])
        end = rnd.choice([0, 16, 32, 64, 96, 128, 160, 192, 224, 255])
        return _gradient(length, start, end)
    elif choice == 7:
        # Blocks of color with variable block size
        block_len = rnd.choice([1,2,3,4,5,6,7,8,16,32,64])
        colors = [rnd.randrange(0,256) for _ in range(rnd.choice([2,3,4,5,6]))]
        return _blocks_of_color(length, block_len, colors)
    elif choice == 8:
        # Low-bit-depth indices (e.g., 2-bit image) to stress small palettes
        bitdepth = rnd.choice([1,2,3,4])  # up to 16 colors
        maxv = (1 << bitdepth) - 1
        return bytes(rnd.randrange(0, maxv + 1) for _ in range(length))
    elif choice == 9:
        # High indices near 255 to stress bounds
        vals = [240,248,250,252,254,255]
        return bytes(rnd.choice(vals) for _ in range(length))
    else:
        # Mixed segments combining patterns
        parts = []
        remaining = length
        while remaining > 0:
            seg_len = rnd.randint(1, max(1, min(64, remaining)))
            sub_choice = rnd.randrange(0, 5)
            if sub_choice == 0:
                parts.append(_pattern_constant(seg_len, rnd.randrange(0,256)))
            elif sub_choice == 1:
                parts.append(_pattern_ramp(seg_len, rnd.randrange(0,256), rnd.choice([1,2,3,5,7,9,15])))
            elif sub_choice == 2:
                parts.append(_pattern_alternating(seg_len, rnd.randrange(0,256), rnd.randrange(0,256)))
            elif sub_choice == 3:
                ps = rnd.choice([2,4,8,16])
                parts.append(_pattern_repeat_block(seg_len, _palette_cycle_block(ps)))
            else:
                parts.append(_blocks_of_color(seg_len, rnd.choice([1,2,4,8]), [rnd.randrange(0,256) for _ in range(3)]))
            remaining -= seg_len
        return b"".join(parts)


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    length = _rand_len(rnd)
    data = _make_interesting_buffer(rnd, length)
    # Ensure byte length bounds (1..1024) and return bytes
    if len(data) < 1:
        data = b"\x00"
    elif len(data) > _MAX_LEN:
        data = data[:_MAX_LEN]
    return data
